'use strict';
// Opening flow and village simulation. Gameplay values for this extension live here.
const LIFE={allocation:8,pillarMin:1,pillarMax:6,startingGold:45,daySeconds:480,hpBase:30,hpPerResilience:10,manaBase:10,manaPerArcane:5,meleeBase:4,meleePerMight:3,forestRisk:.17,roadRisk:.065,encounterGap:22,petHeal:2};
const PILLAR_INFO=[['might','Might','Physical strength and melee damage','⚔'],['wit','Wit','Reasoning and negotiation','◇'],['arcane','Arcane','Magic damage and mana','ϟ'],['instinct','Instinct','Awareness and escape','◉'],['influence','Influence','Trading and persuasion','♧'],['resilience','Resilience','Health and endurance','⬡']];
const GOODS=[{id:'bread',name:'Hearth bread',icon:'◒',price:6,heal:15,desc:'A warm loaf. Restores 15 HP.'},{id:'apple',name:'Orchard apple',icon:'●',price:3,heal:7,desc:'Fresh from the orchard. Restores 7 HP.'},{id:'stew',name:'Garden stew',icon:'♨',price:10,heal:25,desc:'A hearty bowl. Restores 25 HP.'},{id:'fire',name:'Ember Spark',icon:'ϟ',price:22,damage:23,mana:4,desc:'A permanent attack card. 23 damage; 4 mana.'},{id:'herb',name:'Mending Leaf',icon:'❧',price:18,healCard:12,mana:3,desc:'A permanent healing card. Restore 12 HP; 3 mana.'}];
let lifeMode='menu',draft={gender:'male',name:'Traveller',pillars:Object.fromEntries(PILLAR_INFO.map(([id])=>[id,1]))},villagers=[],animals=[],lastClockFrame=0;
let speech=null;
function dismissSpeech(){speech=null;$('speechBubble').hidden=true}
function showSpeech(entity,text,actions=[]){
 speech={entity,text,expires:performance.now()+Math.max(14000,text.length*85)};
 const bubble=$('speechBubble');bubble.innerHTML=`<div class="speaker-name">${escapeText(entity.name)}</div><p role="status">${escapeText(text)}</p>${actions.length?`<div class="speech-actions">${actions.map((a,i)=>`<button data-speech-action="${i}">${escapeText(a.label)}</button>`).join('')}</div>`:''}`;
 bubble.hidden=false;bubble.querySelectorAll('[data-speech-action]').forEach(b=>b.onclick=()=>actions[Number(b.dataset.speechAction)].run());
 if(typeof view!=='undefined')positionSpeech(view.w,view.h,view.ox,view.oy,view.t);
}
function positionSpeech(w,h,ox,oy,t){
 if(!speech)return;
 if(lifeMode!=='play'||atlas||distance(state,speech.entity)>3||performance.now()>speech.expires){dismissSpeech();return}
 const bubble=$('speechBubble'),width=Math.min(300,w-32),height=bubble.offsetHeight||125;
 const x=ox+(speech.entity.x+.5)*t,y=oy+(speech.entity.y+.5)*t;
 const left=Math.max(16,Math.min(w-width-16,x-width/2)),top=Math.max(100,Math.min(h-height-110,y-height-t*.65));
 bubble.style.width=width+'px';bubble.style.left=left+'px';bubble.style.top=top+'px';bubble.style.setProperty?.('--speech-tail',Math.max(20,Math.min(width-20,x-left))+'px');
}
function showQuests(){
 showModal(`<div class="eyebrow">YOUR JOURNEY · CHAPTER I</div><h2>The sleeping gate</h2><p>Recover three relics to awaken the old rift. ${state.relics.length} of 3 recovered.</p><div class="quest-list">${landmarks.filter(p=>p.relic).map(p=>`<div class="quest-item ${state.relics.includes(p.id)?'done':''}"><b>${state.relics.includes(p.id)?'✓':'◇'}</b><span>${p.relic}<small>${p.name}</small></span></div>`).join('')}</div><p>Return to the gate when the three relics are yours.</p>`);
}
let preferences={dayMinutes:8,textScale:100,reduceMotion:false,volume:30};
try{const p=JSON.parse(localStorage.getItem('myworld-settings-v1'));if(p){preferences.dayMinutes=[4,8,12].includes(p.dayMinutes)?p.dayMinutes:8;preferences.textScale=[100,115,130].includes(p.textScale)?p.textScale:100;preferences.reduceMotion=!!p.reduceMotion;preferences.volume=Number.isFinite(p.volume)?Math.max(0,Math.min(100,p.volume)):30}}catch{}
const homeBounds={left:29,right:51,top:31,bottom:53};
function insideVillage(x,y){return x>=homeBounds.left&&x<=homeBounds.right&&y>=homeBounds.top&&y<=homeBounds.bottom}
function isSafe(x,y){return insideVillage(x,y)||landmarks.some(p=>p.kind==='town'&&Math.abs(x-p.x)<=3&&Math.abs(y-p.y)<=3)}
function escapeText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function hydrateLife(){
 if(!state.character)state.character={name:'Traveller',gender:'male',pillars:{might:3,wit:2,arcane:2,instinct:2,influence:2,resilience:3}};
 if(!['male','female'].includes(state.character.gender))state.character.gender='male';
 for(const[id]of PILLAR_INFO){if(!Number.isInteger(state.character.pillars?.[id]))state.character.pillars={might:3,wit:2,arcane:2,instinct:2,influence:2,resilience:3}}
 state.gold=Number.isFinite(state.gold)?Math.max(0,state.gold):LIFE.startingGold;
 state.food=state.food&&typeof state.food==='object'?state.food:{bread:2,apple:2,stew:0};
 state.ownedCards=Array.isArray(state.ownedCards)?state.ownedCards.filter(id=>['fire','herb'].includes(id)):[];
 state.clock=Number.isFinite(state.clock)?state.clock:.32;state.lastEncounter=Number.isFinite(state.lastEncounter)?state.lastEncounter:state.steps;
 if(state.hasCharacter===undefined&&state.steps>0)state.hasCharacter=true;
 if(state.pet&&!['dog','cat','fox','rabbit','sheep','horse','chicken'].includes(state.pet.species))state.pet=null;
 CFG.maxHP=LIFE.hpBase+state.character.pillars.resilience*LIFE.hpPerResilience;
 state.hp=Math.max(0,Math.min(CFG.maxHP,state.hp));state.mana=Math.max(0,Math.min(maxMana(),state.mana));
}
function maxMana(){return LIFE.manaBase+(state.character?.pillars.arcane||2)*LIFE.manaPerArcane}
function meleeDamage(){return LIFE.meleeBase+state.character.pillars.might*LIFE.meleePerMight+Math.floor(state.xp/CFG.levelXP)}
function buildVillage(){
 for(let y=31;y<=53;y++)for(let x=29;x<=51;x++)tiles[idx(x,y)]={type:'grass',v:Math.floor(noise(x,y,91)*4)};
 // Main village lanes and side lanes. Farmland sits behind the player's home.
 for(let y=32;y<=53;y++)for(let x=39;x<=41;x++)tiles[idx(x,y)]={type:'path',v:0};
 for(const y of[38,44,49])for(let x=29;x<=51;x++)tiles[idx(x,y)]={type:'path',v:0};
 for(const x of[32,36,46,49])for(let y=37;y<=50;y++)tiles[idx(x,y)]={type:'path',v:0};
 for(let y=32;y<=36;y++)for(let x=35;x<=45;x++)tiles[idx(x,y)]={type:'farm',v:(x+y)%3};
 for(let y=40;y<=43;y++)for(let x=30;x<=34;x++)tiles[idx(x,y)]={type:'pen',v:0};
 for(let y=40;y<=43;y++)for(let x=46;x<=50;x++)tiles[idx(x,y)]={type:'pen',v:0};
 const buildings=[{id:'bakery',kind:'shop',shop:'food',name:'The Hearth & Loaf',x:35,y:46,desc:'Fresh bread, apples, and a warm bowl of stew.'},{id:'cards',kind:'shop',shop:'cards',name:'The Cardkeeper',x:46,y:46,desc:'A new card can change an entire journey.'},{id:'inn',kind:'safe',name:'The Wayfarer Inn',x:40,y:50,desc:'A clean bed and a friendly welcome.'},{id:'cottage1',kind:'house',name:'Mara’s Cottage',x:32,y:36},{id:'cottage2',kind:'house',name:'The Weaver’s Home',x:49,y:36},{id:'cottage3',kind:'house',name:'The Orchard House',x:31,y:49},{id:'farm',kind:'farm',name:'Your Farmland',x:40,y:34}];
 landmarks.push(...buildings);
 villagers=[{id:'mara',name:'Mara the farmer',x:37,y:37,color:'#bfa46e',text:'This farm is yours to tend. Pick a ripe crop when you need a little food.'},{id:'oren',name:'Oren the baker',x:35,y:48,color:'#c9bda0',text:'Visit the Hearth & Loaf for bread and stew. You can eat from your satchel whenever you need to.'},{id:'sage',name:'Sage the cardkeeper',x:46,y:48,color:'#a19ab8',text:'Might strengthens your strike. Arcane feeds your mana. A good card makes the most of both.'},{id:'warden',name:'Elin the warden',x:40,y:53,color:'#90a5a0',text:'Everyone is safe inside Hearthstead. Yellow roads are safer than the forest, but robbers wait between towns. Watch your step after dark.'},{id:'tess',name:'Tess the shepherd',x:49,y:44,color:'#b0987c',text:'Go on, pet the animals. If you befriend one, it can travel with you. One companion at a time.'},{id:'luca',name:'Luca the stablehand',x:32,y:44,color:'#879b76',text:'The horses are calm here. They like a gentle hand. Look behind your home for the fields.'}];
 animals=[{id:'horse1',species:'horse',name:'Clover',x:31,y:41,home:true},{id:'horse2',species:'horse',name:'Chestnut',x:33,y:42,home:true},{id:'sheep1',species:'sheep',name:'Cloud',x:47,y:41,home:true},{id:'hen1',species:'chicken',name:'Pip',x:49,y:42,home:true},{id:'dog1',species:'dog',name:'Bramble',x:42,y:44,home:true},{id:'cat1',species:'cat',name:'Cinder',x:44,y:39,home:true},{id:'rabbit1',species:'rabbit',name:'Cloverfoot',x:27,y:40,home:false},{id:'fox1',species:'fox',name:'Rustle',x:55,y:45,home:false}];
 for(const a of animals.filter(a=>!a.home)){for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)tiles[idx(a.x+dx,a.y+dy)]={type:'grass',v:1};let x=a.x,y=a.y;while(!insideVillage(x,y)){tiles[idx(x,y)]={type:'grass',v:1};x+=Math.sign(40-x)}}
 // A quiet orchard near the village boundary.
}
function characterPortrait(gender){return `<svg viewBox="0 0 32 42" role="img" aria-label="Generic ${gender} character" shape-rendering="crispEdges"><ellipse cx="16" cy="38" rx="9" ry="2" fill="#15291d"/><path fill="#394b38" d="M11 29h4v9h-4zm7 0h4v9h-4z"/><path fill="${gender==='female'?'#789b87':'#ae935b'}" d="M8 18h16v14H8z"/><path fill="#d9b78b" d="M11 7h11v13H11zM5 20h3v9H5zm19 0h3v9h-3z"/><path fill="#51402c" d="M10 5h13v6H10z${gender==='female'?'M8 8h4v14H8zm13 0h4v14h-4z':''}"/><path fill="#37422f" d="M13 12h2v2h-2zm6 0h2v2h-2z"/><path fill="#dac896" d="M8 25h16v3H8z"/></svg>`}
function applyPreferences(){document.documentElement.style.setProperty('--text-scale',preferences.textScale/100);document.body.classList.toggle('large-text',preferences.textScale>100);if(audioContext){ambientNodes.forEach(o=>{if(o._gain)o._gain.gain.setTargetAtTime(preferences.volume/100*.04,audioContext.currentTime,.1)})}}
function setLifeMode(mode){dismissSpeech();lifeMode=mode;keys.clear();clickTarget=null;lastClockFrame=0;$('opening').hidden=mode==='play';document.body.classList.toggle('in-menu',mode!=='play');if(mode==='play')canvas.focus()}
function mainMenu(){setLifeMode('menu');$('opening').innerHTML=`<div class="opening-brand">✧ <span>MYWORLD</span></div><div class="menu-layout"><div class="menu-story"><div class="eyebrow">YOUR WORLD. YOUR BEGINNING.</div><h1>A little hearth.<br>An endless world.</h1><p>Begin in a village that knows your name.<br>Beyond the fields, the wilderness is waiting.</p><div class="menu-landscape" aria-hidden="true"><span class="menu-moon"></span><span class="menu-mountains"></span><span class="menu-trees">♠ ♠ ♠</span><span class="menu-house">⌂</span><span class="menu-traveller">${characterPortrait('male')}</span><span class="menu-caption">HEARTHSTEAD · YOUR SAFE HAVEN</span></div></div><div class="menu-options"><div class="eyebrow">CHOOSE YOUR ADVENTURE</div><h2>Welcome home.</h2><button class="mode-option active" id="singlePlayer"><span class="mode-symbol">♜</span><span><b>Single Player</b><small>Your character. Your own world.</small></span><span>→</span></button><button class="mode-option" disabled><span class="mode-symbol">♟</span><span><b>Multiplayer</b><small>Explore together</small></span><em>COMING LATER</em></button><button class="mode-option" disabled><span class="mode-symbol">◇</span><span><b>Create a Campaign</b><small>Build a story worth telling</small></span><em>COMING LATER</em></button><button id="menuSettings" class="settings-option">⚙ <span>Settings</span> →</button><p class="menu-footnote">An evolving playable prototype · Single Player available</p></div></div>`;$('singlePlayer').onclick=singlePlayerMenu;$('menuSettings').onclick=()=>settingsScreen('menu')}
function singlePlayerMenu(){setLifeMode('single');$('opening').innerHTML=`<div class="flow-panel narrow"><button class="back-link" id="backMenu">← Main menu</button><div class="eyebrow">SINGLE PLAYER</div><h1>A journey of your own.</h1><p>Your home village, your character, and the world beyond.</p>${state.hasCharacter?`<button class="mode-option active" id="continueGame"><span class="mode-symbol">❧</span><span><b>Continue as ${escapeText(state.character.name)}</b><small>${escapeText(state.seed)} · ${state.relics.length} relics · ${state.gold} gold</small></span><span>→</span></button>`:''}<button class="primary" id="newCharacter">Create a character <span>→</span></button></div>`;$('backMenu').onclick=mainMenu;if($('continueGame'))$('continueGame').onclick=()=>{setLifeMode('play');updateUI()};$('newCharacter').onclick=()=>{draft={gender:'male',name:'Traveller',pillars:Object.fromEntries(PILLAR_INFO.map(([id])=>[id,1]))};characterScreen()}}
function allocationRemaining(){return LIFE.allocation-PILLAR_INFO.reduce((sum,[id])=>sum+draft.pillars[id]-LIFE.pillarMin,0)}
function validCharacter(c){return ['male','female'].includes(c.gender)&&typeof c.name==='string'&&c.name.trim().length>0&&c.name.length<=24&&PILLAR_INFO.every(([id])=>Number.isInteger(c.pillars[id])&&c.pillars[id]>=LIFE.pillarMin&&c.pillars[id]<=LIFE.pillarMax)&&PILLAR_INFO.reduce((s,[id])=>s+c.pillars[id]-1,0)===LIFE.allocation}
function characterScreen(){setLifeMode('character');$('opening').innerHTML=`<div class="flow-panel character-flow"><button class="back-link" id="backSingle">← Single Player</button><div class="eyebrow">A NEW TRAVELLER</div><h1>Who will you become?</h1><p>Choose a starting appearance and shape your strengths. Both appearances use the same rules.</p><div class="character-layout"><section><label for="travellerName">Your name</label><input id="travellerName" maxlength="24" value="${escapeText(draft.name)}"><div class="gender-options">${['male','female'].map(g=>`<button class="gender-card ${draft.gender===g?'selected':''}" data-gender="${g}" aria-pressed="${draft.gender===g}">${characterPortrait(g)}<b>${g==='male'?'Male':'Female'}</b><small>Generic adventurer</small></button>`).join('')}</div><label for="startSeed">World seed</label><input id="startSeed" value="${escapeText(state.seed||'ASHWOOD-724')}" maxlength="32"><label for="startClimate">Landscape</label><select id="startClimate"><option value="woodland">Emerald woodland</option><option value="autumn">Amber wilds</option><option value="frost">Frostbound reach</option></select><div class="creation-summary" id="creationSummary"></div></section><section class="pillar-editor"><div class="allocation-heading"><span>THE SIX PILLARS</span><b id="pointsRemaining"></b></div><p>Each pillar starts at 1. Spend 8 additional points. Maximum 6 per pillar.</p>${PILLAR_INFO.map(([id,name,desc,icon])=>`<div class="allocation-row"><span class="pillar-icon">${icon}</span><div><b>${name}</b><small>${desc}</small></div><button data-adjust="${id},-1" aria-label="Decrease ${name}">−</button><strong id="stat-${id}">1</strong><button data-adjust="${id},1" aria-label="Increase ${name}">+</button></div>`).join('')}<div class="allocation-buttons"><button class="quiet" id="balancedBuild">Balanced build</button><button class="quiet" id="randomBuild">Randomize</button></div></section></div>${state.hasCharacter?'<p class="replace-note">Starting a new journey replaces your current character and world.</p>':''}<button class="primary start-journey" id="startJourney">Start in your village <span>→</span></button></div>`;
 $('backSingle').onclick=singlePlayerMenu;$('travellerName').oninput=e=>{draft.name=e.target.value;refreshAllocation()};$('startClimate').value=state.climate;
 document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{draft.gender=b.dataset.gender;document.querySelectorAll('[data-gender]').forEach(el=>{el.classList.toggle('selected',el.dataset.gender===draft.gender);el.setAttribute('aria-pressed',String(el.dataset.gender===draft.gender))})});
 document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{const[id,change]=b.dataset.adjust.split(','),delta=Number(change);if(delta>0&&allocationRemaining()<=0)return;draft.pillars[id]=Math.max(1,Math.min(6,draft.pillars[id]+delta));refreshAllocation()});
 $('balancedBuild').onclick=()=>{draft.pillars={might:3,wit:2,arcane:2,instinct:2,influence:2,resilience:3};refreshAllocation()};$('randomBuild').onclick=()=>{draft.pillars=Object.fromEntries(PILLAR_INFO.map(([id])=>[id,1]));while(allocationRemaining()>0){const[id]=PILLAR_INFO[Math.floor(Math.random()*6)];if(draft.pillars[id]<6)draft.pillars[id]++}refreshAllocation()};$('startJourney').onclick=startJourney;refreshAllocation()
}
function refreshAllocation(){for(const[id]of PILLAR_INFO)$('stat-'+id).textContent=draft.pillars[id];$('pointsRemaining').textContent=allocationRemaining()+' points left';document.querySelectorAll('[data-adjust]').forEach(b=>{const[id,d]=b.dataset.adjust.split(',');b.disabled=Number(d)>0?(allocationRemaining()===0||draft.pillars[id]>=6):draft.pillars[id]<=1});$('creationSummary').textContent=`${LIFE.hpBase+draft.pillars.resilience*LIFE.hpPerResilience} HP · ${LIFE.manaBase+draft.pillars.arcane*LIFE.manaPerArcane} mana · ${LIFE.meleeBase+draft.pillars.might*LIFE.meleePerMight} melee damage`;$('startJourney').disabled=!validCharacter(draft)}
function startJourney(){draft.name=draft.name.trim();if(!validCharacter(draft))return;const seed=$('startSeed').value.trim()||'ASHWOOD-724',climate=$('startClimate').value;generate(seed,climate);state.character=JSON.parse(JSON.stringify(draft));state.hasCharacter=true;state.pet=null;hydrateLife();state.hp=CFG.maxHP;state.mana=maxMana();setLifeMode('play');goHome(false);notify('Welcome to Hearthstead, '+state.character.name+'. This whole village is your safe haven.');save()}
function settingsScreen(back='menu'){setLifeMode('settings');$('opening').innerHTML=`<div class="flow-panel narrow"><button id="settingsBack" class="back-link">← ${back==='play'?'Back to village':'Main menu'}</button><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Settings</h1><p>Changes apply to this browser and stay with you.</p><label for="dayLength">Day and night cycle</label><select id="dayLength"><option value="4">4 minutes per day</option><option value="8">8 minutes per day</option><option value="12">12 minutes per day</option></select><label for="textScale">Interface text</label><select id="textScale"><option value="100">Standard</option><option value="115">Larger</option><option value="130">Largest</option></select><label for="ambientVolume">Ambient sound volume</label><input id="ambientVolume" type="range" min="0" max="100" value="${preferences.volume}"><label class="motion-setting"><input id="lessMotion" type="checkbox" ${preferences.reduceMotion?'checked':''}> Reduce motion</label><p>Time pauses in menus and conversations. Reduced motion also follows your device preference.</p><button class="primary" id="saveSettings">Save settings <span>✓</span></button><p id="settingsSaved" role="status"></p></div>`;$('dayLength').value=String(preferences.dayMinutes);$('textScale').value=String(preferences.textScale);const exit=()=>back==='play'?setLifeMode('play'):mainMenu();$('settingsBack').onclick=exit;$('saveSettings').onclick=()=>{preferences={dayMinutes:Number($('dayLength').value),textScale:Number($('textScale').value),volume:Number($('ambientVolume').value),reduceMotion:$('lessMotion').checked};try{localStorage.setItem('myworld-settings-v1',JSON.stringify(preferences))}catch{}applyPreferences();$('settingsSaved').textContent='Settings saved.'}}
function nearestLifeEntity(){const candidates=[...villagers,...animals.filter(a=>state.pet?.id!==a.id)].filter(e=>distance(state,e)<=1);return candidates.sort((a,b)=>distance(state,a)-distance(state,b))[0]||null}
function lifeUI(){
 if(!$('lifeStatus'))return;
 const time=Math.floor(state.clock*24*60)%1440,h=Math.floor(time/60),mins=time%60;
 const label=`${h>=6&&h<19?'☀':'☾'} ${String(h).padStart(2,'0')}:${String(mins).padStart(2,'0')} · ${isSafe(state.x,state.y)?'Safe haven':tiles[idx(state.x,state.y)].type==='path'?'Road · stay alert':'Wilderness · danger'}`;
 if($('lifeStatus').textContent!==label)$('lifeStatus').textContent=label;
 $('wallet').textContent=state.gold+' gold';$('petStatus').textContent=state.pet?state.pet.name+' · '+state.pet.species:'No companion yet';$('travellerLabel').textContent=state.character.name;if($('travellerAvatar').dataset.gender!==state.character.gender){$('travellerAvatar').innerHTML=characterPortrait(state.character.gender);$('travellerAvatar').dataset.gender=state.character.gender}
 const entity=nearestLifeEntity();if(entity){$('prompt').hidden=atlas;$('prompt').querySelector('span').textContent=(entity.species?'Greet ':'Talk to ')+entity.name}
 else if(near){const verb=near.kind==='shop'?'Enter ':near.kind==='farm'?'Tend ':near.kind==='house'?'Visit ':near.kind==='safe'?'Rest at ':'Explore ';$('prompt').querySelector('span').textContent=verb+near.name}
 if(insideVillage(state.x,state.y)&&!near)$('locationName').textContent='Hearthstead · your safe village';
}
function buyGood(id){const good=GOODS.find(g=>g.id===id);if(!good)return false;const price=shopPrice(good);if(state.gold<price||state.ownedCards.includes(id))return false;state.gold-=price;if(good.heal)state.food[id]=(state.food[id]||0)+1;else state.ownedCards.push(id);save();updateUI();return true}
function shopPrice(good){return Math.max(1,good.price-Math.max(0,state.character.pillars.influence-2))}
function openShop(p){const goods=GOODS.filter(g=>p.shop==='cards'?!g.heal:!!g.heal);showModal(`<div class="eyebrow">HEARTHSTEAD MARKET</div><h2>${p.name}</h2><p>${p.desc}</p><div class="shop-wallet">Your purse: <b>${state.gold} gold</b></div><div class="shop-list">${goods.map(g=>`<div class="shop-item"><span>${g.icon}</span><div><b>${g.name}</b><small>${g.desc}</small></div><button class="quiet" data-buy="${g.id}" ${state.gold<shopPrice(g)||state.ownedCards.includes(g.id)?'disabled':''}>${state.ownedCards.includes(g.id)?'Owned':shopPrice(g)+' gold'}</button></div>`).join('')}</div><p>Influence can lower prices. Food goes into your satchel; new cards go into your Bustagam.</p><div class="actions">${actionButton('Open satchel','shopSatchel','quiet')}</div>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{if(buyGood(b.dataset.buy)){notify('Purchased '+GOODS.find(g=>g.id===b.dataset.buy).name+'.');openShop(p)}});$('shopSatchel').onclick=openSatchel}
function eatFood(id){const g=GOODS.find(g=>g.id===id&&g.heal);if(!g||!(state.food[id]>0)||state.hp>=CFG.maxHP)return false;state.food[id]--;state.hp=Math.min(CFG.maxHP,state.hp+g.heal);updateUI();save();return true}
function openSatchel(){showModal(`<div class="eyebrow">PROVISIONS & COMPANIONS</div><h2>Your satchel</h2><p>${state.gold} gold · ${state.hp} / ${CFG.maxHP} HP</p><div class="shop-list">${GOODS.filter(g=>g.heal).map(g=>`<div class="shop-item"><span>${g.icon}</span><div><b>${g.name} ×${state.food[g.id]||0}</b><small>Restores ${g.heal} HP</small></div><button class="quiet" data-eat="${g.id}" ${!(state.food[g.id]>0)||state.hp>=CFG.maxHP?'disabled':''}>Eat</button></div>`).join('')}</div><h3>${state.pet?'Your companion: '+escapeText(state.pet.name):'A place for a companion'}</h3><p>${state.pet?'Your '+state.pet.species+' follows you and stays with your saved journey.':'Greet animals in the village or forest. You may keep one companion at a time.'}</p>${state.pet?'<button class="quiet" id="petCompanion">Pet your companion</button>':''}`);document.querySelectorAll('[data-eat]').forEach(b=>b.onclick=()=>{if(eatFood(b.dataset.eat)){notify('You enjoy '+GOODS.find(g=>g.id===b.dataset.eat).name.toLowerCase()+'.');openSatchel()}});if($('petCompanion'))$('petCompanion').onclick=()=>{state.hp=Math.min(CFG.maxHP,state.hp+LIFE.petHeal);save();updateUI();notify(state.pet.name+' leans into your hand. +2 HP.')}}
function keepPet(animal,replace=false){if(state.pet&&state.pet.id!==animal.id&&!replace)return false;state.pet={id:animal.id,species:animal.species,name:animal.name};save();updateUI();return true}
function animalDialog(a){showSpeech(a,'A friendly '+a.species+' watches you curiously.',[
 {label:'Pet '+a.name,run:()=>showSpeech(a,a.name+(a.species==='cat'?' purrs softly.':a.species==='dog'?' wags happily.':' settles beside you.'),animalChoices(a))},
 ...animalChoices(a)
])}
function animalChoices(a){return [{label:state.pet?'Choose as companion':'Keep as companion',run:()=>{
 if(state.pet&&state.pet.id!==a.id)showSpeech(a,state.pet.name+' will return home if you choose '+a.name+'. Travel with '+a.name+' instead?',[
  {label:'Travel with '+a.name,run:()=>{keepPet(a,true);showSpeech(a,a.name+' is now your companion. Your previous pet has returned home.')}},
  {label:'Keep '+state.pet.name,run:()=>showSpeech(a,'Your current companion stays by your side.')}
 ]);else{keepPet(a);showSpeech(a,a.name+' will travel with you. One friend, a whole world to discover.')}
}}]}
function interactLife(){const e=nearestLifeEntity();if(e){if(e.species)animalDialog(e);else showSpeech(e,e.text);return true}if(!near)return false;if(near.kind==='shop'){openShop(near);return true}if(near.kind==='farm'){const ready=state.steps>=(state.nextHarvest||0);showModal(`<div class="eyebrow">THE LAND BEHIND YOUR HOME</div><h2>Your farmland</h2><p>Rows of vegetables grow in the morning light. ${ready?'A small harvest is ready.':'The next crop needs time. Walk around and return later.'}</p><div class="actions">${actionButton(ready?'Gather a harvest':'Growing…','harvest')}</div>`);$('harvest').disabled=!ready;$('harvest').onclick=()=>{if(state.steps<(state.nextHarvest||0))return;state.food.apple=(state.food.apple||0)+2;state.nextHarvest=state.steps+60;closeModal();notify('Harvest gathered. Two fresh apples added to your satchel.')};return true}if(near.kind==='house'){showModal(`<div class="eyebrow">A HOME IN HEARTHSTEAD</div><h2>${near.name}</h2><p>A kettle sings by the hearth. The village feels lived in, and you are welcome here.</p>`);return true}return false}
function encounterTypeAt(x,y,roll){if(isSafe(x,y))return null;return tiles[idx(x,y)].type==='path'?(roll<LIFE.roadRisk?'robber':null):roll<LIFE.forestRisk?'wildlife':null}
function afterTravel(){if(lifeMode!=='play'||combat||$('modal').open||state.steps-state.lastEncounter<LIFE.encounterGap)return;const type=encounterTypeAt(state.x,state.y,random());if(!type)return;state.lastEncounter=state.steps;save();const robber=type==='robber';showModal(`<div class="eyebrow">${robber?'ON THE OLD ROAD':'DEEP IN THE WILDERNESS'}</div><h2>${robber?'A robber blocks the path.':'A wild boar emerges.'}</h2><p>${robber?'“A toll for the road,” says a stranger with a drawn blade. Outside the village, even a yellow road needs caution.':'A startled boar paws the ground. The forest holds friendly creatures and dangerous ones alike.'}</p><div class="actions">${actionButton(robber?'Stand your ground':'Defend yourself','travelFight')}${actionButton(robber?'Pay 8 gold':'Back away','travelAvoid','quiet')}</div><p>${robber?'Paying is possible only if you have 8 gold.':'Backing away returns you to the village safely.'}</p>`);$('travelFight').onclick=()=>startCombat({id:'travel-'+state.steps,kind:'encounter',name:robber?'Roadside Ambush':'Forest Encounter',enemy:robber?'Road Robber':'Wild Boar',encounter:true});$('travelAvoid').disabled=robber&&state.gold<8;$('travelAvoid').onclick=()=>{if(robber){if(state.gold<8)return;state.gold-=8;closeModal();updateUI();notify('You pay the toll and the robber leaves.')}else{closeModal();goHome(false);notify('You leave the boar alone and return safely to Hearthstead.')}}}
function advanceClock(now){if(!lastClockFrame){lastClockFrame=now;return}const dt=Math.min(1000,Math.max(0,now-lastClockFrame));lastClockFrame=now;if(lifeMode!=='play'||$('modal').open)return;state.clock=(state.clock+dt/(preferences.dayMinutes*60000))%1;lifeUI();if(Date.now()-lastSave>10000)save()}
function drawLifeTile(tile,x,y,t,tx,ty){if(tile.type==='farm'){rect(x,y,t,t,'#705c36');for(let i=0;i<3;i++){rect(x+2,y+5+i*9,t-4,3,'#4b4429');const sway=Math.sin(animationTime()/1000+tx+ty)*.7;rect(x+8+sway,y+2+i*9,3,6,'#83a158');rect(x+19+sway,y+1+i*9,3,7,'#a7ad60')}}else if(tile.type==='pen'){rect(x,y,t,t,'#8e8957');if(tx===30||tx===34||tx===46||tx===50){rect(x+3,y,3,t,'#ad9d70');rect(x,y+6,t,3,'#c3b181')}if(ty===40||ty===43){rect(x,y+4,t,3,'#c3b181');rect(x+4,y,3,t*.5,'#a99a6a')}}}
function drawAnimal(a,x,y,t,following=false){const time=animationTime(),bob=Math.sin(time/450+a.x)*.6;const colors={horse:'#886345',sheep:'#ddd7bd',chicken:'#e4d5ab',dog:'#ad8b58',cat:'#858e87',fox:'#bf7d42',rabbit:'#c3c3ad'},c=colors[a.species]||'#ad8b58',big=a.species==='horse',scale=big?1:.72;ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);rect(-t*.3,t*.19,t*.65,t*.15,'#1d372e55');rect(-t*.26,-t*.12+bob,t*.5,t*.32,c);rect(t*.12,-t*.27+bob,t*.24,t*.28,c);rect(t*.22,-t*.2+bob,2,2,'#303c2b');for(const dx of[-.2,.15])rect(t*dx,t*.12,t*.08,t*.2,c);rect(-t*.39,-t*.14+bob,t*.17,t*.07,c);if(['rabbit','horse'].includes(a.species)){rect(t*.13,-t*.48+bob,t*.07,t*.25,c);rect(t*.24,-t*.47+bob,t*.07,t*.23,c)}else if(a.species==='chicken'){rect(t*.22,-t*.34+bob,t*.08,t*.08,'#b15a3d');rect(t*.35,-t*.19+bob,t*.09,t*.06,'#d9ad5e')}else{rect(t*.12,-t*.36+bob,t*.08,t*.12,c);rect(t*.27,-t*.36+bob,t*.08,t*.12,c)}ctx.restore();if(following){ctx.fillStyle='#e8d7a0';ctx.font='9px Georgia';ctx.textAlign='center';ctx.fillText('♥',x,y-t*.5)}}
function drawVillager(n,x,y,t){const bob=Math.sin(animationTime()/750+n.x)*.5;rect(x-t*.18,y+t*.25,t*.4,t*.1,'#213b2b55');rect(x-t*.15,y-t*.08+bob,t*.32,t*.37,n.color);rect(x-t*.1,y-t*.36+bob,t*.24,t*.26,'#c7ac84');rect(x-t*.12,y-t*.4+bob,t*.28,t*.09,'#544932');rect(x-t*.13,y+t*.2,t*.1,t*.17,'#48503a');rect(x+t*.04,y+t*.2,t*.1,t*.17,'#48503a');if(distance(state,n)<=1){ctx.font='9px Georgia';ctx.textAlign='center';ctx.fillStyle='#e5dfba';ctx.fillText(n.name,x,y-t*.65)}}
function drawLifeEntities(ox,oy,t){if(atlas)return;for(const n of villagers){if(state.seen.has(idx(n.x,n.y)))drawVillager(n,ox+(n.x+.5)*t,oy+(n.y+.5)*t,t)}for(const a of animals){if(state.pet?.id===a.id||!state.seen.has(idx(a.x,a.y)))continue;drawAnimal(a,ox+(a.x+.5)*t,oy+(a.y+.5)*t,t)}if(state.pet)drawAnimal({...state.pet,x:state.x},ox+(motion.x+.5-motion.facing*.72)*t,oy+(motion.y+.95)*t,t,true)}
function drawDayNight(w,h,ox,oy,t){if(atlas)return;const hour=state.clock*24;let darkness=hour<5?.48:hour<7?.48*(7-hour)/2:hour<17?0:hour<20?.48*(hour-17)/3:.48;if(darkness<=0)return;rect(0,0,w,h,`rgba(14,24,57,${darkness})`);if(hour>17&&hour<20)rect(0,0,w,h,'#b96c3010');for(const p of landmarks.filter(p=>['safe','shop','house','town'].includes(p.kind))){if(!state.seen.has(idx(p.x,p.y)))continue;const x=ox+(p.x+.5)*t,y=oy+(p.y+.7)*t;const glow=ctx.createRadialGradient(x,y,0,x,y,t*2);glow.addColorStop(0,`rgba(248,202,103,${darkness*.5})`);glow.addColorStop(1,'#eeb76300');ctx.fillStyle=glow;ctx.fillRect(x-t*2,y-t*2,t*4,t*4);rect(x-t*.53,y-t*.1,t*.22,t*.22,'#f3cf7d');rect(x+t*.3,y-t*.1,t*.22,t*.22,'#f3cf7d')}}
function bootGame(){applyPreferences();$('gameMenu').onclick=()=>{save();mainMenu()};$('gameSettings').onclick=()=>settingsScreen('play');$('satchel').onclick=openSatchel;$('questButton').onclick=showQuests;mainMenu()}
